
/* ============================================================
   HUD BAR — 底部状态条
   无限回廊 · 铁锈凝血美学
   ============================================================ */

#hud-bar {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 24px;
  width: 100%;
  padding: 8px 24px;
  background: linear-gradient(
    0deg,
    rgba(8, 5, 4, 0.95) 0%,
    rgba(12, 8, 6, 0.9) 60%,
    transparent 100%
  );
  border-top: 1px solid rgba(60, 30, 20, 0.2);
}

.hud-stat {
  display: flex;
  align-items: center;
  gap: 8px;
  font-family: var(--font-mono);
}

.hud-label {
  font-size: 0.8rem;
  letter-spacing: 2px;
  color: var(--amber-dim);
  width: 36px;
  text-align: right;
  font-family: var(--font-display);
}

.hud-track {
  width: 100px;
  height: 6px;
  background: rgba(20, 12, 8, 0.6);
  border: 1px solid rgba(100, 50, 20, 0.3);
  overflow: hidden;
  border-radius: 2px;
}

.hud-fill {
  height: 100%;
  transition: width 0.6s;
}

.hud-fill.hp {
  background: linear-gradient(90deg, #2a0808, #7a1818);
}

.hud-fill.mp {
  background: linear-gradient(90deg, #2a4040, #4a7060);
}

.hud-fill.sp {
  background: linear-gradient(90deg, #1a0a05, #5a2812);
}

.hud-num {
  font-size: 0.85rem;
  color: var(--chalk);
  min-width: 65px;
  letter-spacing: 1px;
  white-space: nowrap;
}

.hud-num.danger {
  color: var(--blood-wet);
}

.hud-name {
  margin-left: auto;
}

.hud-name .hud-num {
  font-family: var(--font-display);
  font-size: 1rem;
  letter-spacing: 3px;
  color: var(--amber);
  font-weight: 700;
}

/* ============ 响应式 ============ */
@media (max-width: 768px) {
  #hud-bar {
    gap: 10px;
    padding: 6px 10px;
  }

  .hud-track {
    width: 60px;
  }

  .hud-num {
    font-size: 0.72rem;
    min-width: 50px;
  }

  .hud-label {
    font-size: 0.68rem;
    width: 26px;
  }
}

@media (max-width: 480px) {
  #hud-bar {
    gap: 4px;
    padding: 4px 6px;
  }

  .hud-track {
    width: 40px;
    height: 5px;
  }

  .hud-label {
    font-size: 0.6rem;
    width: 22px;
  }

  .hud-num {
    font-size: 0.6rem;
    min-width: 40px;
  }
}
